  if (nameBn.length > 120) {
    throw new HttpError(400, "\u09A8\u09BE\u09AE \u09E7\u09E8\u09E6 \u0985\u0995\u09CD\u09B7\u09B0\u09C7\u09B0 \u09AE\u09A7\u09CD\u09AF\u09C7 \u09A6\u09BF\u09A8\u0964", "bad_name", { field: "nameBn" });
  }
